CREATE TABLE IF NOT EXISTS catalogues(id TEXT PRIMARY KEY, content_hash TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(product_id TEXT PRIMARY KEY, catalogue_id TEXT NOT NULL REFERENCES catalogues(id), data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS facts(fact_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(product_id), predicate TEXT NOT NULL, value_json TEXT NOT NULL, unit TEXT, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS presentations(presentation_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(product_id), condition TEXT NOT NULL, body TEXT NOT NULL, exposed_json TEXT NOT NULL, content_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS query_groups(query_group_id TEXT PRIMARY KEY, suite TEXT NOT NULL, data_json TEXT NOT NULL, content_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY AUTOINCREMENT, put_product_id TEXT NOT NULL, suite TEXT NOT NULL, manifest_hash TEXT NOT NULL, manifest_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', progress INTEGER NOT NULL DEFAULT 0, cancel_requested INTEGER NOT NULL DEFAULT 0, locked INTEGER NOT NULL DEFAULT 0, parent_run_id INTEGER REFERENCES runs(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP, started_at TEXT, completed_at TEXT);
CREATE TABLE IF NOT EXISTS run_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL REFERENCES runs(id), stage TEXT NOT NULL, position INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', started_at TEXT, completed_at TEXT, log_text TEXT DEFAULT '', error_text TEXT, UNIQUE(run_id, stage));
CREATE TABLE IF NOT EXISTS retrieval_traces(run_id INTEGER NOT NULL REFERENCES runs(id), query_group_id TEXT NOT NULL, condition TEXT NOT NULL, channel TEXT NOT NULL, product_id TEXT NOT NULL, score REAL NOT NULL, rank INTEGER NOT NULL, PRIMARY KEY(run_id, query_group_id, condition, channel, product_id));
CREATE TABLE IF NOT EXISTS constraint_traces(run_id INTEGER NOT NULL REFERENCES runs(id), query_group_id TEXT NOT NULL, condition TEXT NOT NULL, product_id TEXT NOT NULL, outcome TEXT NOT NULL, reasons_json TEXT NOT NULL, PRIMARY KEY(run_id, query_group_id, condition, product_id));
CREATE TABLE IF NOT EXISTS llm_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL REFERENCES runs(id), query_group_id TEXT NOT NULL, condition TEXT NOT NULL, trial INTEGER NOT NULL, request_hash TEXT NOT NULL, request_json TEXT NOT NULL, response_json TEXT NOT NULL, provider_model TEXT NOT NULL, status TEXT NOT NULL, latency_ms INTEGER NOT NULL, token_count INTEGER NOT NULL, UNIQUE(run_id, query_group_id, condition, trial));
CREATE TABLE IF NOT EXISTS recommendations(attempt_id INTEGER PRIMARY KEY REFERENCES llm_attempts(id), data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS validations(attempt_id INTEGER PRIMARY KEY REFERENCES llm_attempts(id), valid INTEGER NOT NULL, errors_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metrics(run_id INTEGER NOT NULL REFERENCES runs(id), condition TEXT NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(run_id, condition));
CREATE TABLE IF NOT EXISTS artifacts(id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL REFERENCES runs(id), name TEXT NOT NULL, path TEXT NOT NULL, content_hash TEXT NOT NULL, exportable INTEGER NOT NULL DEFAULT 1);
